css:
* {
  box-sizing: border-box;
}

html,
body {
  width: 100%;
  height: 100%;
  margin: 0;
  overflow: hidden;
  background: transparent !important;
}

.transport-widget {
  position: relative;
  width: 100%;
  height: 100%;
  overflow: hidden;

  background: transparent !important;
  color: #246975;

  font-family: Arial, Helvetica, sans-serif;

  user-select: none;
  pointer-events: none;
  opacity: var(--w-opacity, 1);
}

.transport-stage {
  position: absolute;
  top: 0;
  left: 0;

  width: 1018px;
  height: 708px;

  transform-origin: top left;
  background: transparent !important;
}

.screen-header {
  position: absolute;
  top: 10px;
  left: 25px;
  right: 25px;
  height: 53px;
  overflow: hidden;
}

.screen-title {
  overflow: hidden;

  color: #0E5B67;
  font-size: 26px;
  font-weight: 700;
  line-height: 31px;

  text-overflow: ellipsis;
  white-space: nowrap;
}

.screen-subtitle {
  overflow: hidden;

  color: #728DA5;
  font-size: 14px;
  line-height: 19px;

  text-overflow: ellipsis;
  white-space: nowrap;
}

.screen-subtitle[hidden] {
  display: none;
}

.transport-diagram {
  position: absolute;
  top: 70px;
  left: 25px;

  width: 968px;
  height: 569px;

  overflow: hidden;
  background: transparent;
  font-family: Arial, Helvetica, sans-serif;
}

.section-heading {
  fill: #246975;

  font-family: Arial, Helvetica, sans-serif;
  font-size: 22px;
  font-weight: 700;

  text-anchor: middle;
  text-decoration: underline;
}

.divider-line {
  fill: none;
  stroke: #8C9BA4;
  stroke-width: 3.5;
}

.hatch-area {
  fill: url(#transport-wall-hatching);
  stroke: none;
}

.ground-hatch-area {
  fill: url(#transport-ground-hatching);
  stroke: none;
}

.hatch-line {
  fill: none;
  stroke: #9BAAB4;
  stroke-width: 1;
}

.mechanical-line,
.symbol-line,
.rail-line {
  fill: none;
  stroke: #4E4E4E;
  stroke-width: 1.2;

  stroke-linecap: square;
  stroke-linejoin: miter;
}

.belt-line {
  fill: none;
  stroke: #61727C;
  stroke-width: 1.1;
  stroke-dasharray: 15 7;
}

.point-axis {
  fill: none;
  stroke: #788B97;
  stroke-width: 1.1;
}

.track-axis {
  fill: none;
  stroke: #788B97;
  stroke-width: 1.1;
  stroke-dasharray: 17 9;
}

.machine-body,
.roller-body {
  fill: #D7D8DB;
  stroke: #4E4E4E;
  stroke-width: 1.2;
}

.machine-inset {
  fill: #F4F6F8;
  stroke: #4E4E4E;
  stroke-width: 1.2;
}

.symbol-white,
.motor-circle {
  fill: #FFFFFF;
  stroke: #4E4E4E;
  stroke-width: 1.1;
}

.symbol-mark {
  fill: #4E4E4E;
}

.sensor-tag,
.control-tag,
.equipment-tag {
  fill: #405D6B;

  font-family: Arial, Helvetica, sans-serif;
  font-size: 12px;
  font-style: normal;
  font-weight: 700;
  font-variant: normal;

  letter-spacing: 0;
  text-anchor: middle;
  stroke: none;
}

.motor-letter {
  fill: #4E4E4E;

  font-family: Arial, Helvetica, sans-serif;
  font-size: 13px;
  font-weight: 700;

  text-anchor: middle;
  dominant-baseline: middle;
}

.screen-footer {
  position: absolute;
  top: 647px;
  left: 20px;
  right: 20px;
  height: 59px;

  display: flex;
  align-items: center;
  justify-content: space-between;

  border-top: 1px solid #C8DAE5;
  background: transparent !important;
}

.visual-button {
  display: flex;
  width: 122px;
  height: 36px;

  align-items: center;
  justify-content: center;

  border: 1px solid #4B83A7;
  border-radius: 5px;

  background: linear-gradient(
    180deg,
    #FFFFFF,
    #EEF5F8
  );

  color: #1C5A6B;
  font-size: 13px;
  font-weight: 700;
  line-height: 1;
}

.brand-label {
  display: flex;
  height: 36px;
  align-items: center;

  color: #009999;
  font-size: 23px;
  font-weight: 700;
  line-height: 1;
  letter-spacing: 0.8px;
}

js:
"use strict";

(function () {
  const BASE_WIDTH = 1018;
  const BASE_HEIGHT = 708;

  const DEFAULT_TITLE = "LÍNEA 3 / TRANSPORTADOR";
  const DEFAULT_SUBTITLE =
    "Vista del levantador y carro transportador";

  let root = null;
  let stage = null;
  let latestWidget = null;
  let currentName = null;
  let initialized = false;

  function updateHeader(widget) {
    if (!stage) return;

    const name =
      widget && typeof widget.name === "string"
        ? widget.name.trim()
        : "";

    if (name === currentName) return;
    currentName = name;

    const parts = name.split("//");

    const title =
      (parts[0] || "").trim() || DEFAULT_TITLE;

    const subtitle =
      parts.length > 1
        ? parts.slice(1).join("//").trim()
        : DEFAULT_SUBTITLE;

    const titleNode =
      stage.querySelector(".screen-title");

    const subtitleNode =
      stage.querySelector(".screen-subtitle");

    titleNode.textContent = title;
    subtitleNode.textContent = subtitle;
    subtitleNode.hidden = subtitle === "";
  }

  function fitStage() {
    if (!root || !stage) return;

    const width = root.clientWidth;
    const height = root.clientHeight;

    if (width <= 0 || height <= 0) return;

    const scale = Math.min(
      width / BASE_WIDTH,
      height / BASE_HEIGHT
    );

    stage.style.left =
      (width - BASE_WIDTH * scale) / 2 + "px";

    stage.style.top =
      (height - BASE_HEIGHT * scale) / 2 + "px";

    stage.style.transform =
      "scale(" + scale + ")";
  }

  /*
   * Widget visual sin variables del PLC.
   *
   * NOMBRE permite personalizar:
   * Título//Subtítulo
   */
  window.onWidgetUpdate = function (widget) {
    latestWidget = widget;

    if (initialized) {
      updateHeader(widget);
    }
  };

  function initialize() {
    if (initialized) return;

    root =
      document.querySelector(".transport-widget");

    stage =
      document.querySelector(".transport-stage");

    if (!root || !stage) return;

    initialized = true;

    updateHeader(
      latestWidget || window.WIDGET || null
    );

    fitStage();

    if (typeof ResizeObserver !== "undefined") {
      new ResizeObserver(fitStage).observe(root);
    } else {
      window.addEventListener(
        "resize",
        fitStage
      );
    }
  }

  if (document.readyState === "loading") {
    document.addEventListener(
      "DOMContentLoaded",
      initialize,
      { once: true }
    );
  } else {
    initialize();
  }
})();
